import { prisma } from '@/lib/prisma'

export type PomodoroMode = 'focus' | 'break'

export interface PomodoroSessionInput {
  duration?: number
  type: PomodoroMode
}

export interface PomodoroStats {
  totalSeconds: number
  count: number
}

export interface PomodoroDefaultSettings {
  focus: number
  break: number
}

const DEFAULT_FOCUS_SECONDS = 1500 // 25분
const DEFAULT_BREAK_SECONDS = 300 // 5분

/**
 * ISO 8601 날짜 문자열(yyyy-mm-dd)을 UTC 자정 Date로 파싱한다.
 */
function parseISODateUTC(date: string): Date {
  const [year, month, day] = date.split('-').map(Number)
  return new Date(Date.UTC(year, month - 1, day))
}

function addDaysUTC(date: Date, days: number): Date {
  const result = new Date(date.getTime())
  result.setUTCDate(result.getUTCDate() + days)
  return result
}

function getMonthBoundsUTC(date: Date): { start: Date; end: Date } {
  const start = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), 1))
  const end = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + 1, 1))
  return { start, end }
}

function getWeekBoundsUTC(date: Date): { start: Date; end: Date } {
  const day = date.getUTCDay()
  // 월요일(1)을 주의 시작으로 한다. 일요일(0)은 -6.
  const diff = day === 0 ? -6 : 1 - day
  const start = addDaysUTC(date, diff)
  const end = addDaysUTC(start, 7)
  return { start, end }
}

export function getRangeBounds(
  range: 'day' | 'week' | 'month',
  date: string,
): { start: Date; end: Date } {
  const base = parseISODateUTC(date)
  if (range === 'day') {
    return { start: base, end: addDaysUTC(base, 1) }
  }
  if (range === 'week') {
    return getWeekBoundsUTC(base)
  }
  return getMonthBoundsUTC(base)
}

export async function getPomodoroDefaults(userId: string): Promise<PomodoroDefaultSettings> {
  const settings = await prisma.userSettings.findUnique({ where: { userId } })
  return {
    focus: settings?.pomodoroFocus ?? DEFAULT_FOCUS_SECONDS,
    break: settings?.pomodoroBreak ?? DEFAULT_BREAK_SECONDS,
  }
}

export async function listPomodoroSessions(
  userId: string,
  range: 'day' | 'week' | 'month',
  date: string,
) {
  const { start, end } = getRangeBounds(range, date)
  return prisma.pomodoroSession.findMany({
    where: {
      userId,
      completedAt: {
        gte: start,
        lt: end,
      },
    },
    orderBy: { completedAt: 'desc' },
  })
}

export async function createPomodoroSession(userId: string, input: PomodoroSessionInput) {
  if (input.duration !== undefined && input.duration <= 0) {
    throw new Error('세션 시간은 0보다 커야 합니다.')
  }

  const defaults = await getPomodoroDefaults(userId)
  const duration = input.duration ?? (input.type === 'focus' ? defaults.focus : defaults.break)

  if (duration <= 0) {
    throw new Error('세션 시간은 0보다 커야 합니다.')
  }

  return prisma.pomodoroSession.create({
    data: {
      userId,
      duration,
      type: input.type,
    },
  })
}

export async function getPomodoroStats(
  userId: string,
  range: 'day' | 'week' | 'month',
  date: string,
): Promise<PomodoroStats> {
  const { start, end } = getRangeBounds(range, date)
  const sessions = await prisma.pomodoroSession.findMany({
    where: {
      userId,
      completedAt: {
        gte: start,
        lt: end,
      },
      type: 'focus',
    },
  })

  const totalSeconds = sessions.reduce((sum, session) => sum + session.duration, 0)
  return { totalSeconds, count: sessions.length }
}

import { Request, Response, NextFunction, Router } from 'express'
import { z } from 'zod'
import { requireAuth } from '@/middleware/auth'
import {
  createPomodoroSession,
  listPomodoroSessions,
  getPomodoroStats,
  PomodoroSessionInput,
} from '@/services/pomodoro'

const router = Router()

const rangeSchema = z.enum(['day', 'week', 'month'])

const isoDateRegex = /^\d{4}-\d{2}-\d{2}$/
const dateStringSchema = z
  .string()
  .regex(isoDateRegex, 'yyyy-mm-dd 형식의 날짜를 입력하세요.')
  .default(() => new Date().toISOString().slice(0, 10))

const sessionsQuerySchema = z.object({
  range: rangeSchema.default('day'),
  date: dateStringSchema,
})

const statsQuerySchema = z.object({
  range: rangeSchema.default('day'),
  date: dateStringSchema,
})

const createSessionBodySchema = z.object({
  duration: z.coerce.number().int().positive().optional(),
  type: z.enum(['focus', 'break']),
})

type AsyncHandler = (req: Request, res: Response, _next: NextFunction) => Promise<void>

function asyncRoute(handler: AsyncHandler) {
  return (req: Request, res: Response, next: NextFunction) => {
    handler(req, res, next).catch(next)
  }
}

router.get(
  '/sessions',
  requireAuth,
  asyncRoute(async (req, res) => {
    const userId = req.user!.id
    const parsed = sessionsQuerySchema.safeParse(req.query)
    if (!parsed.success) {
      res.status(400).json({ error: parsed.error.errors[0].message })
      return
    }

    const { range, date } = parsed.data
    const sessions = await listPomodoroSessions(userId, range, date)
    res.json({ sessions })
  }),
)

router.post(
  '/sessions',
  requireAuth,
  asyncRoute(async (req, res) => {
    const userId = req.user!.id
    const parsed = createSessionBodySchema.safeParse(req.body)
    if (!parsed.success) {
      res.status(400).json({ error: parsed.error.errors[0].message })
      return
    }

    const input: PomodoroSessionInput = {
      duration: parsed.data.duration,
      type: parsed.data.type,
    }

    const session = await createPomodoroSession(userId, input)
    res.status(201).json({ session })
  }),
)

router.get(
  '/stats',
  requireAuth,
  asyncRoute(async (req, res) => {
    const userId = req.user!.id
    const parsed = statsQuerySchema.safeParse(req.query)
    if (!parsed.success) {
      res.status(400).json({ error: parsed.error.errors[0].message })
      return
    }

    const { range, date } = parsed.data
    const stats = await getPomodoroStats(userId, range, date)
    res.json(stats)
  }),
)

export default router

