import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { render, screen, waitFor } from '@testing-library/react'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import Pomodoro from '@/pages/Pomodoro'

const mockMutate = vi.fn()

vi.mock('@/api/pomodoro', () => ({
  useCreatePomodoroSession: () => ({
    mutate: mockMutate,
    isPending: false,
  }),
  usePomodoroStats: () => ({
    data: undefined,
    isLoading: false,
  }),
}))

const queryClient = new QueryClient()

function wrapper({ children }: { children: React.ReactNode }) {
  return <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
}

describe('Pomodoro page', () => {
  beforeEach(() => {
    vi.useFakeTimers()
    queryClient.clear()
    mockMutate.mockClear()
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  it('집중 모드와 기본 시간이 표시된다', () => {
    render(<Pomodoro />, { wrapper })
    expect(screen.getByText('뽀모도로 타이머')).toBeDefined()
    expect(screen.getByText('집중')).toBeDefined()
    expect(screen.getByText('25:00')).toBeDefined()
  })

  it('시작 버튼을 누르면 타이머가 작동하고 일시정지할 수 있다', async () => {
    render(<Pomodoro />, { wrapper })
    const startButton = screen.getByRole('button', { name: '시작' })
    startButton.click()

    expect(screen.getByText('진행 중...')).toBeDefined()

    vi.advanceTimersByTime(1000)
    await waitFor(() => {
      expect(screen.getByText('24:59')).toBeDefined()
    })

    const pauseButton = screen.getByRole('button', { name: '일시정지' })
    pauseButton.click()

    expect(screen.getByText('일시정지됨')).toBeDefined()
  })

  it('집중 시간이 끝나면 세션 생성 API를 호출한다', async () => {
    render(<Pomodoro />, { wrapper })

    // 집중 시간을 1초로 설정
    const focusInput = screen.getByLabelText('집중')
    focusInput.setAttribute('value', '0')
    focusInput.dispatchEvent(new Event('change', { bubbles: true }))

    const applyButton = screen.getByRole('button', { name: '적용' })
    applyButton.click()

    await waitFor(() => {
      expect(screen.getByText('01:00')).toBeDefined()
    })

    const startButton = screen.getByRole('button', { name: '시작' })
    startButton.click()

    vi.advanceTimersByTime(61000)

    await waitFor(() => {
      expect(mockMutate).toHaveBeenCalledWith({ duration: 60, type: 'focus' })
    })
  })
})

